import icalendar
from datetime import datetime

def is_holiday(date: str) -> bool:
    try:
        dt = datetime.strptime(date, "%Y-%m-%d")
        cal = icalendar.Calendar().from_string(open("calendars/company_2025.ics", "rb").read())
        for component in cal.walk():
            if component.name == "VEVENT":
                event_date = datetime.strptime(component.get("DTSTART").dt.strftime("%Y-%m-%d"), "%Y-%m-%d")
                if event_date == dt:
                    return True
        return False
    except:
        return False

